/**
 * How the Groups page names a group's kind and scope, and the body it sends to create one. Free
 * of React so the web tests cover it.
 */

/** The fields of a group row this module reads. */
export interface GroupRow {
    isSystemGroup?: boolean;
    isAutoGenerated?: boolean;
    spaceId?: string | null;
    certificateAuthorityId?: string | null;
}

/**
 * A group's kind. Auto-generated groups are either one CA's (`<space>-<ca>-*` or an instance
 * CA's) or a whole space's (`space-<slug>-*`: a space and no CA).
 */
export type GroupKind = 'system' | 'space' | 'ca' | 'custom';

export function groupKind(g: GroupRow): GroupKind {
    if (g.isSystemGroup) return 'system';
    if (!g.isAutoGenerated) return 'custom';
    return g.spaceId != null && !g.certificateAuthorityId ? 'space' : 'ca';
}

const KIND_LABELS: Record<GroupKind, string> = { system: 'System', space: 'Space (Auto)', ca: 'CA (Auto)', custom: 'Custom' };

/** The Type column's label. */
export function groupTypeLabel(g: GroupRow): string {
    return KIND_LABELS[groupKind(g)];
}

/** The Type filter's options, in the order the select lists them. */
export const GROUP_TYPE_FILTERS: ReadonlyArray<{ value: GroupKind; label: string }> = [
    { value: 'system', label: KIND_LABELS.system },
    { value: 'space', label: KIND_LABELS.space },
    { value: 'ca', label: KIND_LABELS.ca },
    { value: 'custom', label: KIND_LABELS.custom },
];

/**
 * The Scope column: "Instance" for no space, else the space's name from the first source that
 * knows it. A space id is never shown; one no source names reads "Unknown space".
 */
export function groupScopeName(g: GroupRow, spaceNames: ReadonlyMap<string, string>): string {
    if (g.spaceId == null) return 'Instance';
    return spaceNames.get(g.spaceId) || 'Unknown space';
}

/**
 * Space id to name from every source the page has, earliest winning: the system-admin space
 * list, then `/me` capabilities, then the CA list. Blank names are skipped.
 */
export function spaceNameMap(...sources: ReadonlyArray<ReadonlyArray<{ id?: string | null; name?: string | null }>>): Map<string, string> {
    const out = new Map<string, string>();
    for (const list of sources) {
        for (const s of list) {
            if (s.id && s.name && !out.has(s.id)) out.set(s.id, s.name);
        }
    }
    return out;
}

/** The space select's value for an instance group. */
export const INSTANCE_GROUP_SCOPE = 'instance';

/** What the create form holds. */
export interface CreateGroupForm {
    name: string;
    displayName: string;
    templateName: string | null;
    certificateAuthorityId: string;
    spaceId: string;
}

/**
 * The create request. A CA-scoped group takes its space from the CA; a space-wide group names
 * its space; an instance group names neither and says `scope: "instance"`, because the server
 * refuses a create with no CA, no space and no explicit instance scope.
 */
export function createGroupBody(form: CreateGroupForm): Record<string, unknown> {
    const base = { name: form.name, displayName: form.displayName, templateName: form.templateName };
    if (form.certificateAuthorityId) return { ...base, certificateAuthorityId: form.certificateAuthorityId, spaceId: null };
    if (form.spaceId === INSTANCE_GROUP_SCOPE) return { ...base, certificateAuthorityId: null, spaceId: null, scope: 'instance' };
    return { ...base, certificateAuthorityId: null, spaceId: form.spaceId || null };
}
